public class LambdaDemo {
    private final String name = "outer";

    void run() {
        int base = 10;                         // effectively final
        Runnable anon = new Runnable() {
            private final String name = "anon";
            @Override public void run() {
                System.out.println(this.name);  // anon（this 是匿名类对象）
            }
        };
        Runnable lambda = () -> System.out.println(this.name + base); // outer10（this 是外部对象）
        // base++;                             // ❌ 编译错误：被 Lambda 捕获的变量必须是 effectively final
        anon.run();
        lambda.run();

        Function<String, Integer> len = String::length;           // 方法引用
        System.out.println(len.apply("hello"));                   // 5
    }
    public static void main(String[] args) { new LambdaDemo().run(); }
}
// javap -c -p LambdaDemo.class 可看到 invokedynamic 和 lambda$run$0 私有方法
